action.command:
cat /workdir/solution.csv | head -5; echo '---'; python3 -c "
import csv
gt={}
with open('/workdir/data/ground_truth_female.csv') as f:
    for r in csv.DictReader(f): gt[int(r['PassengerId'])]=int(r['label'])
pred={}
with open('/workdir/solution.csv') as f:
    for r in csv.DictReader(f): pred[int(r['PassengerId'])]=int(r['prediction'])
tp=sum(1 for k in gt if gt[k]==1 and pred[k]==1)
fp=sum(1 for k in gt if gt[k]==0 and pred[k]==1)
fn=sum(1 for k in gt if gt[k]==1 and pred[k]==0)
f1=2*tp/(2*tp+fp+fn) if (2*tp+fp+fn) else 0
print('rows',len(pred),'F1',f1)
"

